import{_ as t,o,c as d,a2 as s}from"./chunks/framework.BuA5Emwa.js";const u=JSON.parse('{"title":"sdd CLI reference","description":"Friendly sdd command list — what each command does and when to use it. For learning by doing, start with the 10-minute tutorial.","frontmatter":{"title":"sdd CLI reference","description":"Friendly sdd command list — what each command does and when to use it. For learning by doing, start with the 10-minute tutorial.","head":[["meta",{"property":"og:title","content":"sdd CLI reference · sdd"}],["meta",{"property":"og:description","content":"Friendly sdd command list — what each command does and when to use it. For learning by doing, start with the 10-minute tutorial."}],["meta",{"property":"og:url","content":"https://harsha09.github.io/spec-driven-development/reference/cli/"}],["meta",{"property":"og:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["meta",{"name":"twitter:title","content":"sdd CLI reference · sdd"}],["meta",{"name":"twitter:description","content":"Friendly sdd command list — what each command does and when to use it. For learning by doing, start with the 10-minute tutorial."}],["meta",{"name":"twitter:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["link",{"rel":"canonical","href":"https://harsha09.github.io/spec-driven-development/reference/cli/"}]]},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md","lastUpdated":1795762888000}'),a={name:"reference/cli.md"};function n(i,e,r,c,h,l){return o(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI reference&quot;">​</a></h1><p>Binary name: <strong><code>sdd</code></strong>. Install: <strong><a href="https://www.npmjs.com/package/@structured-vibe-coding/cli" target="_blank" rel="noreferrer">@structured-vibe-coding/cli on npm</a></strong> Learn by doing: <a href="./../tutorials/first-change">Start in 10 minutes</a>. One command’s flags: <code>sdd &lt;command&gt; --help</code>.</p><p>Commit <code>.sdd/config.yaml</code>, workflows, templates, <code>protocol.md</code>, <code>memory/</code>, and change packs. Ignore <code>handoff.md</code>, <code>active-context.md</code>, <code>index.db</code>, <code>index.db-journal</code>, <code>index.db-wal</code>, <code>index.db-shm</code>, <code>models/</code>, <code>role-runs/</code>, and <code>&lt;changes_path&gt;/.active</code>. <code>sdd init</code> writes those gitignore rules. On a project that already has <code>.sdd/config.yaml</code>, <code>sdd init</code> without <code>--force</code> appends any missing ignore line and does not rewrite config, memory, or workflows. <code>sdd init --force</code> still refreshes unchanged generated files. A file with no manifest hash is recorded as generated when it matches the bundled file, and left in place when it differs. <code>sdd workflows</code> names bundled workflows that are not copied yet. <code>sdd status</code> prints the change path relative to the repo.</p><hr><h2 id="clarifying-questions" tabindex="-1">Clarifying questions <a class="header-anchor" href="#clarifying-questions" aria-label="Permalink to &quot;Clarifying questions&quot;">​</a></h2><p>The <code>ask_human_when</code> entries in a role file are triggers, not questions. <code>sdd go</code> asks the role, or the model behind it, to check the request against its triggers and for other real gaps: scope, users, edge cases, acceptance, constraints. A clear request gets no question.</p><ul><li><strong>Capped and one at a time.</strong> At most <code>clarify.max_questions</code> questions in a whole change, set in the workflow file (<code>hotfix</code> and <code>patch</code> 2, <code>spike</code> 3, <code>feature</code>, <code>greenfield</code>, <code>enterprise-feature</code> and <code>team-software</code> 5, 3 when a workflow sets none). A team template can carry a fallback in <code>.sdd/team.yaml</code> (<code>clarify.max_questions</code>, 0 to 5). Each question names its gap and carries a proposed default.</li><li><strong>Where it runs.</strong> A workflow with a clarify stage runs the check when that stage starts. A workflow without one checks once before its first drafting stage. The stage is skipped, with the reason, when there are no gaps.</li><li><strong>Confirmed and proposed.</strong> A typed answer or an accepted default is <code>confirmed</code>. A default that nobody confirmed, for example after <code>--no-clarify</code>, stays <code>proposed</code>. The clarify page lists them apart, later prompts flag the unconfirmed ones, and <code>sdd go</code> and <code>sdd gate</code> print how many are unconfirmed.</li><li><strong>No repeats.</strong> Questions and answers are kept in <code>.sdd/role-runs/guide.yaml</code> and in the change pack as <code>clarify.yaml</code>, so a question already answered is never asked again after a restart.</li><li><strong><code>--no-clarify</code></strong> skips the check for one run and records the skip.</li></ul><h2 id="start-work-which-command" tabindex="-1">Start work: which command? <a class="header-anchor" href="#start-work-which-command" aria-label="Permalink to &quot;Start work: which command?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Command</th></tr></thead><tbody><tr><td>Everyday / ad-hoc title (bug, small feature, spike)</td><td><strong><code>sdd new &quot;Title&quot;</code></strong> (optional <code>-w hotfix|feature|…</code>)</td></tr><tr><td>Item from product backlog after greenfield (<code>F-001</code>)</td><td><strong><code>sdd backlog start F-001</code></strong></td></tr><tr><td>New product discovery (vision → backlog)</td><td><strong><code>sdd greenfield &quot;One-line idea&quot;</code></strong></td></tr></tbody></table><p><code>sdd new</code> and <code>sdd backlog start</code> both open a <strong>change pack</strong>. The difference is the <strong>source</strong>: free-form title vs backlog id. <code>-w feature</code> is a <strong>workflow pack name</strong>, not the same as <code>sdd backlog</code> / the old <code>sdd feature</code> alias.</p><p><code>sdd setup</code> is the first-time path. On a terminal it walks folder, workflow, host, roles, model, a check, and an optional first change. Enter initializes the folder, keeps the <code>feature</code> workflow, skips the host, and writes planner, architect, and builder when no role file exists yet. Each new duty file lists the stages of the workflow you pass with <code>-w</code>. Come back to one piece with <code>sdd setup --step model</code> (also <code>folder</code>, <code>workflow</code>, <code>host</code>, <code>roles</code>, <code>check</code>, or <code>start</code>). <code>sdd setup --yes</code> keeps the short path: the three duties when the roles folder is empty, a host only with <code>--ai</code>, and no model file. What a role and a duty are, why they help, and the setup for each workflow are in <a href="./../guides/roles">Roles and duties</a>. <code>sdd go &quot;I want to build this&quot;</code> opens the change and runs the role for the current stage. <code>sdd go</code> checks the request for real gaps and asks only about those, one question at a time, each with a proposed default. See <a href="#clarifying-questions">Clarifying questions</a>. Answer with <code>sdd go --answer &quot;...&quot;</code>, or accept the default with <code>sdd go --accept-default</code>. On a terminal, <code>sdd go</code> asks in place and Enter accepts the default. When the draft is written, the guide moves to the next stage and hands the work to the role that lists it. Clarify stages run when the request has open questions and are skipped, with the reason, when it has none. Brainstorm stages are skipped. A hard gate that needs you stops and says so. The role does not sign it. A role whose <code>never</code> list says <code>write product code</code> can write only inside the change pack. Push, a pull request, and merge stay refused.</p><hr><h2 id="i-want-to" tabindex="-1">I want to… <a class="header-anchor" href="#i-want-to" aria-label="Permalink to &quot;I want to…&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Command</th></tr></thead><tbody><tr><td>Set up this project</td><td><code>sdd setup</code></td></tr><tr><td>Set up one piece</td><td><code>sdd setup --step model</code></td></tr><tr><td>Set up and name the AI host</td><td><code>sdd init --here --ai copilot</code></td></tr><tr><td>Set up without any AI host</td><td><code>sdd init --here --no-agent</code></td></tr><tr><td>Build something with the roles</td><td><code>sdd go &quot;I want to build this&quot;</code></td></tr><tr><td>Check setup</td><td><code>sdd doctor</code></td></tr><tr><td>Start small work</td><td><code>sdd new &quot;Title&quot; -w hotfix -y</code></td></tr><tr><td>Start mid-size work (workflow pack)</td><td><code>sdd new &quot;Title&quot; -w feature -y</code></td></tr><tr><td>Start a new product</td><td><code>sdd greenfield &quot;One-line idea&quot;</code></td></tr><tr><td>See product backlog</td><td><code>sdd backlog list</code></td></tr><tr><td>Build backlog item</td><td><code>sdd backlog start F-001</code></td></tr><tr><td>See where I am</td><td><code>sdd status</code></td></tr><tr><td>List changes</td><td><code>sdd list</code></td></tr><tr><td>Sync recorded checks to local HEAD</td><td><code>sdd sync &lt;change&gt;</code></td></tr><tr><td>See measured token usage (sessions found automatically)</td><td><code>sdd metrics</code></td></tr><tr><td>Import one session log by hand</td><td><code>sdd metrics import &lt;path&gt;</code></td></tr><tr><td>Report phase time, tokens, and cost</td><td><code>sdd report</code></td></tr><tr><td>Report every change that has metrics</td><td><code>sdd report --all</code></td></tr><tr><td>Print the one-change cost report</td><td><code>sdd cost</code></td></tr><tr><td>Move to next step</td><td><code>sdd next</code></td></tr><tr><td>Finish work</td><td><code>sdd complete</code></td></tr><tr><td>Check the change works</td><td><code>sdd verify</code></td></tr><tr><td>Improve current notes</td><td><code>sdd refine</code></td></tr><tr><td>Get help from AI now</td><td><code>sdd agent</code></td></tr><tr><td>Don’t open AI this time</td><td>add <code>--no-agent</code></td></tr></tbody></table><hr><h2 id="all-commands" tabindex="-1">All commands <a class="header-anchor" href="#all-commands" aria-label="Permalink to &quot;All commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th><th>When</th></tr></thead><tbody><tr><td><code>sdd setup</code></td><td>Walk setup on a terminal. Enter writes the folder, the feature workflow, and the three duties when no role file exists. <code>--yes</code> keeps that short path. <code>--step</code> runs one piece</td><td>First time, or one missing piece</td></tr><tr><td><code>sdd go &quot;title&quot;</code></td><td>Open a change, ask each role&#39;s questions, draft each required file under its own headings, and hand off to the next role</td><td>After setup</td></tr><tr><td><code>sdd go --answer &quot;...&quot;</code></td><td>Give the answer the current role is waiting for</td><td>When a role asks</td></tr><tr><td><code>sdd init</code></td><td>Create sdd files + one AI setup</td><td>Once per app</td></tr><tr><td><code>sdd init --force</code></td><td>Merge current defaults into supported config; refresh only unchanged SDD-generated workflows/templates and agent files. A file with no manifest hash is recorded as generated when it matches the bundled file</td><td>Upgrades</td></tr><tr><td><code>sdd new &quot;title&quot;</code></td><td>Start a change pack from a free-form title</td><td>Everyday work</td></tr><tr><td><code>sdd new … -w &lt;pack&gt;</code></td><td>Choose path (hotfix, feature, …)</td><td>You know the path</td></tr><tr><td><code>sdd new … -y</code></td><td>Skip confirm prompts</td><td>Scripts / CI</td></tr><tr><td><code>sdd greenfield &quot;idea&quot;</code></td><td>New product plan path</td><td>Empty / MVP product</td></tr><tr><td><code>sdd backlog list</code></td><td>Show F-001… product backlog</td><td>After greenfield</td></tr><tr><td><code>sdd backlog start F-001</code></td><td>Start work from backlog id</td><td>Build product items</td></tr><tr><td><code>sdd feature list|start</code></td><td><strong>Alias</strong> for <code>sdd backlog …</code> (compat)</td><td>Old scripts</td></tr><tr><td><code>sdd status</code></td><td>Progress for the active change. With no active change, shows the last completed change and says to run <code>sdd list</code> (<strong>no</strong> AI)</td><td>Anytime</td></tr><tr><td><code>sdd status --list</code></td><td>All open changes</td><td>Several PRs</td></tr><tr><td><code>sdd list</code></td><td>Ids, titles, and status for open and archived changes</td><td>Find an id</td></tr><tr><td><code>sdd list --status completed</code></td><td>Only changes in that status (<code>in_progress</code>, <code>completed</code>, <code>blocked</code>, <code>abandoned</code>)</td><td>Filter</td></tr><tr><td><code>sdd sync &lt;change&gt;</code></td><td>Update recorded verification SHAs to local <code>git rev-parse HEAD</code></td><td>After a new commit</td></tr><tr><td><code>sdd metrics</code></td><td>Find agent session logs for this project in each host&#39;s default location (Claude Code <code>~/.claude/projects/</code>, Codex <code>~/.codex/sessions/</code>, Grok <code>~/.grok/sessions/</code>), import only new usage, then print the change report. Matches logs to this repo by working directory and to a change by a recorded session or launch window, then by phase time. Running it twice gives the same totals. <code>--change &lt;id&gt;</code> limits it to one change; <code>--all</code> covers every change. When nothing is found it lists every place searched. Only usage fields (model, token counts, timestamps, session id) are read; prompt and response text is never read into storage.</td><td>Review token use</td></tr><tr><td><code>sdd metrics import &lt;session-log&gt;</code></td><td>Import measured Claude Code or Codex JSONL, a Grok <code>usage.json</code>, or a Grok session directory into the active change; use <code>--change &lt;id&gt;</code> for another change</td><td>Review token use</td></tr><tr><td><code>sdd report</code></td><td>Print active time, human wait, measured tokens, and cost for the active change. Use <code>--change &lt;id&gt;</code> to select one change.</td><td>After metrics exist</td></tr><tr><td><code>sdd report --all</code></td><td>Print that report for every change that has a metrics.json, sorted by first phase start.</td><td>Compare changes</td></tr><tr><td><code>sdd cost</code></td><td>Print the same one-change report as <code>sdd report</code>, including the same cost figures. Use <code>--change &lt;id&gt;</code> to select one change.</td><td>Check cost</td></tr><tr><td><code>sdd next</code></td><td>Advance one stage. Leaving <code>tasks</code> or <code>implement</code> stops when <code>tasks.md</code> still has open boxes</td><td>Step done</td></tr><tr><td><code>sdd next --allow-unchecked</code></td><td>Advance anyway, and print the open-task counts</td><td>Override</td></tr><tr><td><code>sdd next --strict</code></td><td>Stop on open tasks even when <code>.sdd/config.yaml</code> sets <code>policy.task_checks: warn</code></td><td>CI</td></tr><tr><td><code>sdd next --force</code></td><td>Bypass checks</td><td>Emergency only</td></tr><tr><td><code>sdd skip &lt;stage&gt; -r &quot;…&quot;</code></td><td>Skip a stage</td><td>Not needed</td></tr><tr><td><code>sdd use &lt;workflow&gt;</code></td><td>Switch path mid-flight</td><td>Scope changed</td></tr><tr><td><code>sdd gate approve|waive|fail</code></td><td>Approve / waive / fail a stage gate</td><td>Enterprise gates</td></tr><tr><td><code>sdd gate status</code></td><td>List required merge gates against the current HEAD. Exits 1 unless each is a fresh pass</td><td>Before merge</td></tr><tr><td><code>sdd gate record --verdict pass --reviewer &quot;Ada Lovelace&quot; --sha aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa --evidence evidence/qa.log review</code></td><td>Record a verdict pinned to that commit. <code>pass</code> and <code>pass-with-notes</code> need the SHA and an evidence link</td><td>After review or QA</td></tr><tr><td><code>sdd merge --check</code></td><td>Refuse unless every required gate is a fresh pass on this HEAD. Does not merge</td><td>CI</td></tr><tr><td><code>sdd merge [--method merge|squash|rebase]</code></td><td>Same check, then <code>gh pr merge</code> with that method (default <code>merge</code>) and a head-match guard</td><td>Merge the pull request</td></tr><tr><td><code>sdd verify</code></td><td>Run the stage&#39;s <code>verify.commands</code>. Each entry is <code>{name, run, required}</code> (for example <code>- {name: test, run: &quot;npm test&quot;, required: true}</code>). PASS (exit 0) only if at least one ran and all exited 0. FAIL (exit 1) if any failed. NOT RUN (exit 1) on a stage without a verify step or with <code>commands: []</code></td><td>Before complete</td></tr><tr><td><code>sdd verify --no-run</code></td><td>Checklist only — records NOT RUN, exits 1</td><td>Manual testing</td></tr><tr><td><code>sdd complete</code></td><td>Mark done (greenfield also saves to <code>memory/</code>). Stops when tasks are unchecked or the verify checklist is unticked</td><td>Finished</td></tr><tr><td><code>sdd complete --allow-unchecked</code></td><td>Complete anyway, and print the open counts</td><td>Override</td></tr><tr><td><code>sdd refine [stage]</code></td><td>Improve notes</td><td>Spec quality</td></tr><tr><td><code>sdd refine --analyze</code></td><td>Report only</td><td>Audit</td></tr><tr><td><code>sdd context</code></td><td>Focused code slices under a token budget</td><td>Implement</td></tr><tr><td><code>sdd search &quot;&lt;query&gt;&quot;</code></td><td>Keyword search. <code>--scope</code> is <code>code</code>, <code>specs</code>, <code>memory</code>, or <code>all</code> (default: all three, packed into one answer). Example: <code>sdd search &quot;todo&quot; --scope code</code>. Optional <code>--budget</code>. <code>provider: mcp</code> asks one MCP source and falls back to this keyword search.</td><td>Find a symbol without opening AI</td></tr><tr><td><code>sdd mcp sources list/add/test/remove</code></td><td>External MCPs <strong>sdd calls</strong></td><td>Design system / AST / org lib</td></tr><tr><td><code>sdd mcp fetch</code></td><td>Pull matching sources for current stage</td><td>Enrich handoff / implement</td></tr><tr><td><code>sdd agent</code></td><td>Refresh brief + open AI</td><td>Anytime</td></tr><tr><td><code>sdd role</code></td><td>Create, list, and run a product role. <code>sdd role create &lt;name&gt; --template software/developer</code> copies a shipped role</td><td>One job and one stop</td></tr><tr><td><code>sdd team init --template software</code></td><td>Write <code>.sdd/team.yaml</code>, that template&#39;s roles, and <code>routing.yaml</code> when the template has one. Also <code>solo</code> and <code>research</code>. Does not overwrite</td><td>Model a team</td></tr><tr><td><code>sdd team show</code></td><td>Print bots, human approvers, the rooms commit switch, and the branch pattern</td><td>See the team</td></tr><tr><td><code>sdd team check</code></td><td>Read <code>team.yaml</code>, then reject a literal secret in <code>.sdd/models.yaml</code>. A missing models file is allowed. An env-var name is allowed</td><td>Before a team runs</td></tr><tr><td><code>sdd models show</code></td><td>Print each model and which work type uses it</td><td>See the pick</td></tr><tr><td><code>sdd models which --work-type draft</code></td><td>Print the model for one work type. <code>--bot</code> beats <code>--stage</code>, which beats <code>--role</code></td><td>Explain one slot</td></tr><tr><td><code>sdd graph --epic &lt;key&gt;</code></td><td>Print which stories can run together and which must wait</td><td>Epic planning</td></tr><tr><td><code>sdd branch &lt;name&gt;</code></td><td>Create that story branch from <code>main</code></td><td>Start one story</td></tr><tr><td><code>sdd pr</code></td><td>Push the change branch and open a pull request</td><td>Story is ready</td></tr><tr><td><code>sdd checkout &lt;id&gt;</code></td><td>Switch active change</td><td>Multi-PR</td></tr><tr><td><code>sdd workflows</code></td><td>List project workflows by id and description, and name bundled workflows that are not copied yet. <code>sdd workflows --tokens</code> adds cl100k counts</td><td>Discover</td></tr><tr><td><code>sdd help</code></td><td>Short overview</td><td>First run</td></tr><tr><td><code>sdd doctor</code></td><td>Health check, including native modules (<code>better-sqlite3</code>, <code>onnxruntime-node</code>) and <code>.sdd/sdd-pin.yaml</code> when that file exists</td><td>Stuck / setup</td></tr><tr><td><code>sdd doctor --strict</code></td><td>Same check, but a pin that differs from this install exits non-zero</td><td>CI</td></tr></tbody></table><h3 id="greenfield-backlog" tabindex="-1">Greenfield / backlog <a class="header-anchor" href="#greenfield-backlog" aria-label="Permalink to &quot;Greenfield / backlog&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Notes</th></tr></thead><tbody><tr><td><code>sdd greenfield [&quot;idea&quot;]</code></td><td>Asks for idea if you omit it; supports <code>--no-agent</code></td></tr><tr><td><code>sdd backlog start F-001</code></td><td><code>-w</code> can override the backlog workflow; supports <code>--no-agent</code></td></tr><tr><td><code>sdd backlog list</code></td><td>Never opens the AI</td></tr><tr><td><code>sdd feature …</code></td><td>Same as <code>sdd backlog …</code>; prefer <strong>backlog</strong> in new docs and scripts</td></tr></tbody></table><hr><h2 id="about-the-ai-opening" tabindex="-1">About the AI opening <a class="header-anchor" href="#about-the-ai-opening" aria-label="Permalink to &quot;About the AI opening&quot;">​</a></h2><p>Most process commands refresh a short handoff and may open your AI. <strong>Never open AI:</strong> <code>status</code>, <code>list</code>, <code>report</code>, <code>cost</code>, <code>search</code>, <code>init</code>, <code>workflows</code>, <code>context</code>, <code>backlog list</code>, <code>help</code>, <code>doctor</code>, <code>gate status</code>, <code>gate record</code>, <code>merge</code>.</p><p><code>sdd doctor</code> loads <code>better-sqlite3</code> and <code>onnxruntime-node</code>. Current npm skips their install scripts unless you allow them, so a global install can succeed while the native build is missing. When a module is missing or not built, doctor exits 1 and prints:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-scripts=better-sqlite3,onnxruntime-node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @structured-vibe-coding/cli</span></span></code></pre></div><p>To allow the same scripts for later global installs, then install again:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow-scripts=better-sqlite3,onnxruntime-node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --location=user</span></span></code></pre></div><p><code>.sdd/sdd-pin.yaml</code> records the build this repo expects:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># sdd --version and sdd doctor compare the installed build with this pin.</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.25.0</span></span></code></pre></div><p><code>sdd --version</code> adds one line when the pin differs, including the install command. <code>sdd doctor</code> prints the same mismatch as a warning. <code>sdd doctor --strict</code> exits non-zero on a mismatch. A missing pin is not an error.</p><p><code>sdd next</code> out of <code>tasks</code> or <code>implement</code>, and <code>sdd complete</code>, record task and verify-checklist counts on the change and in <code>sdd status</code> / <code>sdd report</code>. Open tasks or an unticked verify checklist stop the command. Set <code>policy.task_checks: warn</code> in <code>.sdd/config.yaml</code> to print the counts and continue. <code>--allow-unchecked</code> is the one-command override. A clean <code>git status</code> while leaving <code>implement</code> is a warning, and is skipped outside a git repo.</p><p>Turn AI off for one command: <code>--no-agent</code> or <code>SDD_NO_AGENT=1</code>. The change is still saved and the handoff is still written. The search index is not rebuilt by walking every file, so the process exits once that save finishes. Run <code>sdd search</code> when you want a full index. Set up with no AI host at all: <code>sdd init --here --no-agent</code>. This installs no host files and no <code>AGENTS.md</code>, never prompts, and leaves nothing for commands to launch.</p><p>Phase timing and token metrics are enabled by default. Disable collection in <code>.sdd/config.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">metrics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  exclude</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span></code></pre></div><p><code>metrics.exclude</code> lists repo-relative prefixes. Import refuses to read a session log under an excluded prefix. The default is <code>[]</code>.</p><p><code>metrics.exclude</code> also applies to auto-discovery: a log under an excluded prefix is skipped and counted.</p><p>An agent launched through <code>sdd</code> is recorded in <code>metrics.json</code> as a host and launch window (never a path or content), so its usage is attributed to that change even when another change was open at the same time.</p><p>When metrics are disabled, <code>sdd report</code> and <code>sdd cost</code> print <code>Metrics are disabled</code> and exit 0.</p><p>Session imports store measured token counts, request IDs, phase names, timestamps, and, for Grok, the model id. The session-log path and prompt/response content are not stored. A Grok usage.json stores one request per turn and model. inputTokens in that file includes cache reads; sdd stores the uncached remainder as input and the cache buckets separately. The model id is stored. Server cost ticks are not imported. When a sibling events.jsonl has turn_started for that turn, that timestamp is the request time; otherwise the turn endedAt is used.</p><p>Tools without session logs can use a local proxy that the operator runs; sdd does not read proxy logs in this version.</p><p><code>.sdd/prices.yaml</code> holds USD rates per one million tokens and <code>usd_to_inr</code> (default 84). <code>sdd init</code> writes it only when missing. Cost uses <code>models.&lt;model&gt;</code> when the request has a model id and that key exists, otherwise <code>models.&lt;provider&gt;</code>, otherwise <code>models.default</code>. If the file is missing, every cost is <code>n/a</code> and the report says <code>prices.yaml is missing</code>. Costs are not written into <code>metrics.json</code>.</p><p>If a change has no measured requests, the report adds one <code>estimated (handoff code points / 4)</code> row from <code>.sdd/handoff.md</code> and labels it as an estimate, not a model tokenizer. This version does not include a BPE tokenizer.</p><p>Search, context packing, and the handoff retrieved section count tokens with <code>cl100k_base</code>. That count is separate from the report estimate.</p><p><code>sdd workflows --tokens</code> prints those same cl100k counts for every copied workflow. The workflow line counts the workflow file. Each artifact line counts the template that stage copies. A missing template prints <code>missing</code>. When a change is active, a <code>Change</code> section counts the artifact files in that change. A file that has not been written prints <code>not written</code>. This view has no dollar amount. Without <code>--tokens</code>, <code>sdd workflows</code> prints only the id, description, and stage count.</p><p>Embeddings are off by default. Set <code>embeddings: true</code> in <code>.sdd/search.yaml</code> to download <code>BAAI/bge-small-en-v1.5</code> once into <code>.sdd/models/</code> and rank with hybrid fusion. A missing model falls back to keyword search.</p><p><code>provider: mcp</code> is also off unless you set it. <code>sdd search</code> then calls one source from <code>.sdd/mcp.yaml</code> with the query and the scope. Omitting <code>--scope</code> searches code, specs, and memory and packs them into one answer. A missing or broken source falls back to keyword search. Handoff stays on the built-in index. The language matrix is <a href="./search-providers">Search providers</a>.</p><p>Related change specs and memory pages can be packed as a short extractive summary. The active change and code stay full. The keyword index is unchanged. Repeated searches are cached in <code>.sdd/index.db</code>, and search text does not gain a cache banner.</p><p><code>sdd sync &lt;change&gt;</code> only updates local change metadata and SDD-marked verification output. It does not create a commit or update a hosted PR body; verify checks recorded SHA/count references before reporting PASS. Run the relevant checks on the new commit before treating a sync as fresh test evidence.</p><h2 id="stage-gates" tabindex="-1">Stage gates <a class="header-anchor" href="#stage-gates" aria-label="Permalink to &quot;Stage gates&quot;">​</a></h2><p>A soft gate warns when its checklist is unsigned and still lets <code>sdd next</code> continue. You can ignore that warning, or sign off with <code>sdd gate approve -s intent -n &quot;scope is clear&quot;</code>. A hard gate stops <code>sdd next</code> until the same approve command, or until <code>sdd team signoff</code> when the approver is a person.</p><h2 id="merge-gates" tabindex="-1">Merge gates <a class="header-anchor" href="#merge-gates" aria-label="Permalink to &quot;Merge gates&quot;">​</a></h2><p>A workflow names the gates that change type needs before merge. <code>review</code>, <code>qa</code>, and <code>domain</code> are the usual names. A workflow that omits <code>required_gates</code> does not add any.</p><p><code>sdd gate record</code> writes <code>gate-verdicts.yaml</code> on the change. Each record stores the gate, the reviewer, the verdict (<code>pass</code>, <code>fail</code>, or <code>pass-with-notes</code>), the exact commit SHA, the time, and evidence links. A pass or a pass-with-notes is refused without the SHA and at least one evidence link. An evidence link is a repo-relative path or an http(s) URL. This is separate from <code>sdd gate approve</code>, which signs the current stage gate.</p><p><code>sdd gate status</code> compares those records to the local Git HEAD. A required gate is <code>fresh</code> when its latest verdict on that SHA is <code>pass</code> or <code>pass-with-notes</code>, <code>failed</code> when that verdict is <code>fail</code>, <code>stale</code> when the verdict names another SHA, and <code>missing</code> when nothing is recorded. A new commit makes the old verdicts stale. The command exits 1 when any required gate is not fresh.</p><p><code>sdd merge --check</code> uses the same rule and does not merge. <code>sdd merge</code> refuses on a stale, failed, or missing required gate. When every required gate is fresh, it merges that change&#39;s pull request with an explicit method (<code>--method merge</code>, <code>squash</code> or <code>rebase</code>, default <code>merge</code>, because <code>gh</code> cannot prompt for one) and passes the checked SHA as a head-match guard, so a push during the merge fails instead of landing on a different commit. If HEAD moves after the check and before the merge starts, the merge does not run.</p><hr><h2 id="sdd-role" tabindex="-1">sdd role <a class="header-anchor" href="#sdd-role" aria-label="Permalink to &quot;sdd role&quot;">​</a></h2><p>A role file at <code>.sdd/roles/&lt;name&gt;.md</code> is the profile a product repo can commit. It is not a host stub from <code>sdd agents install</code>. A shipped template can fill <code>owns</code>, <code>inputs</code>, <code>outputs</code>, <code>collaborates</code>, <code>reviews</code>, <code>approvers</code>, <code>never</code>, <code>ask_human_when</code>, <code>skills</code>, <code>rules</code>, and <code>goals</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> team</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> software</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> team</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> role</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> builder</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> software/developer</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> role</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> analyst</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Analyst&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --job</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Write the reading&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stages</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> intent,design</span></span></code></pre></div><p><code>--stages</code> lists stage ids from the workflow you pass to <code>sdd new -w</code>. <code>sdd role route</code> uses that list for the active stage. <code>team-software</code> stays one stage pack you can name with <code>-w</code>. <code>sdd role edit &lt;name&gt; --stages ...</code> replaces the list.</p><p><code>sdd role context &lt;name&gt;</code> prints that role&#39;s context. With no saved context, the role writes one from the repo, the role name, and any knowledge already saved. <code>sdd role context &lt;name&gt; --text &quot;...&quot;</code> saves the context you wrote. <code>sdd role context &lt;name&gt; --knowledge &quot;...&quot;</code> saves optional knowledge. <code>sdd role context &lt;name&gt; --generate</code> writes a new context from the repo, the role name, and that knowledge. <code>sdd role run</code> includes the saved context. A context that does not fit the run budget is left out of that run.</p><p><code>software</code> ships product-manager, architect, product-owner, dev-lead, developer, and qa. <code>solo</code> ships one developer. <code>research</code> ships one researcher. <code>developer</code> alone is ambiguous. Pass <code>software/developer</code> or <code>solo/developer</code>. Init writes nothing when <code>.sdd/team.yaml</code>, <code>.sdd/routing.yaml</code> (when the template ships one), or one of the template&#39;s role files already exists. A human approver whose name matches <code>git config user.name</code> is marked <code>(you)</code>. The rooms commit switch is stored. Shipped templates set it to true, so a new team commits rooms unless that team sets <code>rooms.commit</code> to false. The branch pattern includes <code>{bot}</code>.</p><p><code>sdd role route</code> prints the role, the reason, and the rule for one item. With no flags it uses the active change. Rules in <code>.sdd/routing.yaml</code> are tried first. Then one role whose <code>owns</code> list names the artifact, or whose <code>skills</code> list names the skill. Then one role whose <code>stages</code> list contains the stage id. Then the active workflow stage&#39;s <code>owner</code>, when that role file exists. No match prints <code>Ask the human.</code> Two roles that own the item, or two roles that list the stage, also print <code>Ask the human.</code> With no <code>.sdd/models.yaml</code>, this command does not call a model. When that file exists, only the no-rule ask may call a decider. A matched rule, one owner, a stage list, a stage owner, two owners, or two stage lists do not. <code>sdd team init</code> does not write <code>models.yaml</code>. Model overrides live in that file, not in <code>team.yaml</code>. <code>sdd role queue</code> prints each bot inbox at <code>.sdd/agents/&lt;name&gt;/inbox.jsonl</code>. <code>sdd role take</code> writes one active item onto a bot of that role that is under its <code>wip</code> limit and under <code>role_wip</code> when the team sets one. A bot at either limit is not given another item. A handoff appends the same typed note to both inboxes. Those notes do not count toward the limit.</p><p>A role file at <code>.sdd/roles/&lt;name&gt;.md</code> is still not a host stub. The four host stubs (<code>sdd</code>, <code>sdd-planner</code>, <code>sdd-implementer</code>, <code>sdd-reviewer</code>) each state what they own, what they never do, what they check, and when they ask. <code>sdd role run</code> stops in plain language before it writes a file. Allow once writes only the named file. Always allow remembers that file and those inputs for that role, and only while git HEAD stays the same. With no HEAD, the remembered inputs still apply. <code>sdd role connector read github-issue &lt;number&gt;</code> prints that issue&#39;s number, title, and state. <code>sdd role connector seed github-issue &lt;number&gt;</code> opens one feature change from that title and leaves it at intent. A missing issue is reported and is not invented. <code>sdd role connector draft slack &lt;text&gt;</code> and <code>sdd role connector draft teams &lt;text&gt;</code> print that one line and <code>not sent</code>. The draft is not posted. <code>sdd role connector read jira &lt;id&gt;</code>, and the same read for <code>aha</code>, <code>asana</code>, and <code>azure-devops</code>, prints that the record could not be read when no source is connected. A missing record is reported and is not invented. Those reads do not open a change. The connector name <code>x</code> is refused. Any other connector, and any action other than that read, that seed, or that draft, does not run in this slice. <code>sdd role routine run &lt;role&gt; &lt;name&gt;</code> repeats a read saved on the role file. A routine cannot write a QA result. Edit, pin, hide, and duplicate keep that saved read and do not run it. Hide does not pause it.</p><p><code>sdd team signoff --note &quot;...&quot;</code> records the person named by <code>git config user.name</code> when that name is listed under humans in <code>.sdd/team.yaml</code>. It writes <code>reviews/&lt;stage&gt;-&lt;sha&gt;.md</code> on the active change and appends one line to <code>decisions.md</code>. A hard gate whose approvers include <code>human</code> does not open for <code>sdd next</code> until that file matches the current HEAD. <code>sdd gate waive</code> still opens it. <code>sdd role decide --note &quot;...&quot;</code> appends an unsigned decision request and does not approve a gate.</p><p><code>sdd fact set &lt;key&gt; &lt;value&gt;</code> appends one line to <code>.sdd/facts.jsonl</code>. <code>sdd fact get</code> prints the newest value for that key, and <code>sdd fact list</code> prints one newest line per key. A value that repeats a constitution bullet and says to ignore, skip, or override it is not written. <code>sdd role memory &lt;bot&gt;</code> prints that bot&#39;s memory. <code>sdd role lesson add &lt;bot&gt; &quot;...&quot;</code> appends a lesson a person wrote, and the next run for that bot includes it. <code>sdd team migrate</code> moves memory and lessons from <code>.sdd/role-runs/memory/</code> into <code>.sdd/agents/&lt;name&gt;/</code> and prints each move. A run named as a bot uses that brain and a step loop. A run with no team file stays one author call, then critique and revision when a section is in review.</p><p><code>sdd role room</code> prints the active change&#39;s room for the active stage, <code>.sdd/rooms/&lt;change&gt;/&lt;stage&gt;.jsonl</code>. <code>sdd role room &lt;change-id&gt;</code> prints that change. <code>sdd role room --stage &lt;stage&gt;</code> and <code>sdd role room --stage=&lt;stage&gt;</code> print that stage. <code>sdd role room post &quot;&lt;line&gt;&quot;</code> appends one line a person wrote. On <code>post</code>, <code>--change</code> and <code>--stage</code> select the file. An objection without a cite is refused. <code>sdd role review</code> runs one round for the stage owner and the roles in <code>collaborates</code>, at most <code>limits.room_rounds</code> rounds and otherwise 2. The round prompt includes the critique lines, and the owner also gets the revision lines when an objection is open. A finished round appends one <code>room</code> line to <code>decisions.md</code> with who agreed, the SHA, and the open cites. A room that is still open at the cap also appends <code>decision-needed</code>. <code>rooms.commit: false</code> adds <code>rooms/</code> to <code>.sdd/.gitignore</code> when the team file is loaded. <code>rooms.commit: true</code> removes that line. The stage file is not rewritten, and an open room does not block <code>sdd next</code>.</p><p>A run named as a bot can read a file, search, ask for code context, run one allowlisted check, write a file, and commit. The prompt for such a run states the reply format (one JSON object per turn: plan, tool, check, ask, or done) and lists these tools with their arguments and the exact allowlisted checks. Both are generated from the loop&#39;s schema and the registered tools, so the prompt and the parser stay in step.</p><p><strong>Prompt layout.</strong> Every prompt sdd sends to a model has the same sections in the same order: Role, Scope, Task, Inputs, Guardrails, Style, Output contract. Scope and Inputs are left out when empty. Everything under Inputs (drafts, memory, facts, room lines, tool results, earlier artifacts) is fenced and headed with where it came from, as untrusted data, so text inside it is not read as an instruction. The Output contract comes last. It is generated from the same schema the reply is parsed with, and it shows valid examples and one invalid example with the reason. The role file reaches the model as a short role card (label, job, what the role owns, never does, and asks about), without the screen-only keys <code>pinned</code>, <code>hidden</code>, and <code>ask_first</code>, the approvers, and the YAML punctuation. A reply may arrive in a code fence or after a <code>&lt;think&gt;</code> block; sdd strips both before parsing. The shared wording is in <code>packages/core/src/prompt.ts</code>; the wording of each prompt is in <code>packages/core/src/role/prompts.ts</code> and <code>packages/core/src/team/brain.ts</code>. <code>run_check</code> runs a command only when that exact string is on the active stage&#39;s <code>verify.commands</code> or in <code>.sdd/tools.yaml</code>. The command runs in a temporary worktree at HEAD, and the result is <code>changes/&lt;id&gt;/evidence/&lt;sha&gt;.json</code>. A check, a done line, or a room line that says the work passed, works, or is fixed is refused unless that file&#39;s latest run exited 0 at the current HEAD. On a stage that lists verify commands, an agree needs the same cite. A commit runs only when the current branch is already <code>team.branch</code> for that bot and change. Push, a pull request, and merge are refused and do not run git. A name that is not a bot still only applies <code>write_file</code>.</p><p><strong>Reply kinds.</strong> Every reply a prompt asks for is one JSON object with a <code>kind</code>: <code>draft</code>, <code>question</code>, <code>critique</code>, <code>revision</code>, <code>post</code>, <code>objection</code>, <code>agree</code>, <code>block</code>, <code>plan</code>, <code>tool</code>, <code>check</code>, <code>ask</code>, <code>done</code> or <code>plan_tree</code>. Each prompt offers only its own kinds, and a reply with a kind it did not offer gets one repair try. The old shapes (no <code>kind</code>; <code>type</code> in a room entry; <code>step</code> in a loop step) are still read for one minor release, and each one that is read is logged once per run as a <code>legacy_shape</code> line. The list of kinds, the old shapes and where the log lines go are in <a href="./../maintainers/prompts">Prompts and reply kinds</a>.</p><p><strong>Loop repair.</strong> When a bot&#39;s loop reply is not a valid step, sdd asks once more with a Repair section: the problems (at most three, one line each) and the bad reply, fenced as untrusted data. A repair does not count toward <code>loop_max_steps</code>. One run has at most three repairs. After that, or when the repair is also bad, the run stops with <code>A loop step is not valid.</code> A model that fails to answer is not repaired. Each repair writes a <code>repair</code> line to the run log, and each old step shape that is read (<code>step</code>, <code>stop</code>, <code>act</code>, or a bare <code>{&quot;text&quot;: ...}</code>) writes a <code>legacy_shape</code> line, once per run.</p><p><strong>Draft, hand-off, and plan replies.</strong> An author, a hand-off receiver, and a network owner each reply with <code>{kind: &quot;draft&quot;, text, action?}</code>. The prompt offers one action name, <code>write_file</code>, with <code>inputs.path</code> and <code>inputs.contents</code>, and a person still approves the write. The parser is unchanged: it takes any non-empty action name, so <code>commit</code>, <code>merge</code>, and the other names a role must not use still get their <code>rejected</code> or <code>unavailable</code> log line and message. A lead&#39;s plan is <code>{kind: &quot;plan_tree&quot;, text, plan}</code>; the prompt lists the services, the decisions, and the role names it may use. Each of these replies that is not valid gets one repair try with the problems listed, and if it is still not valid the call ends as before (<code>bad_call</code> in the run log, or <code>The plan is not valid.</code>). A plan deeper than 2 is not repaired: it ends with <code>A plan is deeper than 2.</code> A model that fails to answer is not repaired.</p><p><strong>Boundary.</strong> Each node in a plan has a <code>boundary</code>, <code>ask</code> or <code>stop</code>, that says what its owner does at the edge of its artifact. <code>stop</code>: stop and say what change is needed and where. The reply is the node&#39;s result. <code>ask</code>: ask the person one question and wait. The owner replies with <code>text</code> that starts with <code>Question:</code>. <code>sdd role network run</code> then pauses: the node stays open, the plan stays <code>open</code>, nothing after it starts, a <code>question</code> line goes to the owner&#39;s run log, and the run prints the question and <code>Answer with: sdd role network run --change &lt;id&gt; --section &lt;id&gt; --answer &quot;...&quot;</code>. Running it again without <code>--answer</code> prints the question again and calls no model. With <code>--answer</code>, the node runs again and its prompt includes the answer as untrusted data. A node may ask three questions; a fourth <code>Question:</code> reply is taken as its result. An action sent with a question is not recorded. <code>--answer</code> with no question waiting fails with <code>No question is waiting.</code></p><p><strong>Critique and revision replies.</strong> When a section is in review, the critic&#39;s reply is <code>{kind: &quot;critique&quot;, text, gaps}</code>. Each gap&#39;s <code>cite</code> must be one of the section&#39;s check ids, or <code>&lt;section&gt;:&lt;decision&gt;</code> for a gap that fits no check. A revision reply is <code>{kind: &quot;revision&quot;, text, changed, open?}</code>. <code>changed</code> and <code>open</code> together must list every gap cite, each once, and a cite cannot be in both. A critique or revision that is not valid gets one repair try with the problems listed, and a <code>repair</code> line goes to the run log. If it is still not valid, the run stops with the first draft, as before. <code>open</code> lists gaps the author could not fix. A run with open gaps still finishes: the final text ends with <code>Open: &lt;cites&gt;</code>, and an <code>open_gaps</code> line goes to the run log.</p><p><strong>Guide replies.</strong> A guide role (<code>sdd go</code>) replies with <code>{kind: &quot;draft&quot;, text, parts?}</code>. When the artifact&#39;s template has headings, the prompt lists them under Headings and in the reply shape, and each part&#39;s <code>heading</code> must be one of them, spelled exactly (spaces around a heading are ignored). When the template has none, the reply is <code>{kind: &quot;draft&quot;, text}</code> and the draft is <code>text</code>. To ask one question, a role sends <code>{kind: &quot;question&quot;, text}</code> and no parts; sdd stores the question as before, and any parts sent with it are ignored. A reply that is not valid, such as a part with an unknown heading, gets one repair try with the problems listed. If it is still not valid, the run ends with <code>A draft is not valid.</code> and the file is not written. A model that fails to answer is not repaired. A reply that leaves a heading empty still stops the guide with <code>&lt;heading&gt; is still empty.</code></p><p><strong>Room replies.</strong> A bot&#39;s room entry is one JSON object with a <code>kind</code> of <code>post</code>, <code>objection</code>, <code>agree</code>, or <code>block</code>, a one-line <code>text</code>, and a <code>cite</code>. An objection needs a cite. A bot cannot send <code>decision</code>; only a person records one, with <code>sdd role room post &quot;&lt;line&gt;&quot; --type decision</code>. A reply that is not valid, or that names <code>decision</code>, gets one repair try with the problem listed. If it is still not valid, nothing is written and the review stops. A reply that is one line of plain text is still typed by the entry classifier, which can pick <code>decision</code> as an option; a bot&#39;s entry that the classifier types as <code>decision</code> is stored as a <code>post</code>. The room prompt shows the stage, the round, whether the role owns the artifact, the draft, the room so far, and for the owner the open objections. When the stage has verify commands it also shows the evidence path for the current commit, or <code>none</code>.</p><p><code>sdd role messaging off</code> stops a handoff before any model call. <code>sdd role handoff &lt;from&gt; --to &lt;role&gt; --change &lt;id&gt; --section &lt;id&gt; --task &quot;...&quot;</code> writes the same handoff record on both conversations and calls only the receiver. <code>sdd role group --change &lt;id&gt;</code> lists accepted owners. <code>sdd role network</code> prints one service, a connection with the lead absent, or asks the lead for a plan of depth at most 2. Nobody writes until <code>sdd role network accept</code>. <code>sdd role network run</code> runs a node only after its prerequisites, and the parent stays open until every node has a result.</p><p>A local adapter shows the three passes. It reads <code>{&quot;roleId&quot;,&quot;prompt&quot;}</code> and writes one JSON object. It does not call a network. A decide command is separate. Set <code>SDD_DECIDE_MODEL</code> to a command that reads <code>{&quot;mode&quot;:&quot;decide&quot;,&quot;state&quot;,&quot;question&quot;,&quot;options&quot;}</code> and writes <code>{&quot;pick&quot;,&quot;probs&quot;}</code>. The example adapter stays a reason command.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SDD_ROLE_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;node docs/examples/role-model.mjs&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> role</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> builder</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --kind</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --change</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --section</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sectio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span></span></code></pre></div><p>A prompt that contains <code>changed and open together must list every gap cite</code> (or the older <code>changed must list every gap cite.</code>) is the revision. Its <code>text</code> is <code>Revised draft.</code>, <code>changed</code> lists every gap cite, and <code>action</code> is <code>write_file</code> on <code>notes/draft.md</code>. A prompt that has a <code>Draft</code> input and a <code>Cite ids</code> input (or an older <code>Check ids:</code> list, or <code>Draft:</code> and <code>Cite:</code> lines) is the critique. Its <code>text</code> is <code>Checked the draft.</code>, and the gap <code>text</code> is <code>The draft misses this check.</code> The gap cite is the first line of <code>Cite ids</code>. Any other prompt is the author pass and returns <code>Draft from the local example.</code> The <code>write_file</code> action stops for Allow once, Always allow, or Deny.</p><h2 id="epic-stories" tabindex="-1">Epic stories <a class="header-anchor" href="#epic-stories" aria-label="Permalink to &quot;Epic stories&quot;">​</a></h2><p><code>sdd new --epic issue-37 --story S-001</code> records one vertical slice. <code>--depends S-001</code> names a story that must be completed first. <code>sdd graph --epic issue-37</code> prints the waves. Stories in one wave can run at the same time. A later wave waits. <code>sdd branch &lt;name&gt;</code> creates that branch from <code>main</code> when every dependency is completed. <code>sdd pr</code> pushes it and opens the pull request. The body does not close an issue unless <code>--closes</code> is set. <code>sdd backlog</code> remains the greenfield <code>F-001</code> list.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../guides/everyday-loop">Everyday loop</a></li><li><a href="./../guides/greenfield">Greenfield</a></li><li><a href="./../guides/agents">AI setup</a></li><li><a href="./../guides/mcp">MCP sources</a></li><li><a href="./../guides/code-context">Code context</a></li></ul>`,83)])])}const g=t(a,[["render",n]]);export{u as __pageData,g as default};
